function downloadCsv(name,rows){track('download',{format:'csv',file:name});const url=URL.createObjectURL(new Blob(['﻿'+rows.map(r=>r.map(csvCell).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}));saveFile(name,url);setTimeout(()=>URL.revokeObjectURL(url),1000)}
// PNG: copy the computed chart styles inline so the SVG renders the same outside the page.
function svgPng(svg,name){if(!svg)return;track('download',{format:'png',file:name});const clone=svg.cloneNode(true),src=[...svg.querySelectorAll('*')],dst=[...clone.querySelectorAll('*')];src.forEach((el,i)=>{const cs=getComputedStyle(el);for(const p of ['fill','stroke','stroke-width','stroke-dasharray','font-family','font-size','font-weight','opacity'])dst[i].style.setProperty(p,cs.getPropertyValue(p))});const vb=svg.viewBox.baseVal,sc=4,w=vb.width*sc,h=vb.height*sc;clone.setAttribute('width',w);clone.setAttribute('height',h);const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');g.fillStyle=css('--surface');g.fillRect(0,0,w,h);g.drawImage(img,0,0,w,h);saveFile(name+'.png',c.toDataURL('image/png'))};img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(clone))}
function toggleFull(el){if(document.fullscreenElement)document.exitFullscreen();else if(el.requestFullscreen)el.requestFullscreen()}
// Phones: a picked station opens in a sheet over the map, moved clear of it; the handle expands, collapses or closes it.
function pickStation(idx,pan){showStation(idx,pan,true);if(phone.matches)openSheet()}
function openSheet(){const sh=$('sheet');document.body.classList.add('sheetopen');sh.classList.remove('expanded');sh.scrollTop=0;requestAnimationFrame(()=>{const s=D.stations[selected],top=sh.getBoundingClientRect().top,r=map.getContainer().getBoundingClientRect(),y=r.top+map.latLngToContainerPoint([s.lat,s.lon]).y;if(top>r.top+80&&y>top-40)map.panBy([0,y-(r.top+top)/2])})}
function closeSheet(){document.body.classList.remove('sheetopen')}
// Without the Fullscreen API (iPhone) the map expands to fill the window instead; either way the time slider goes with it.
function withTime(on){const t=document.querySelector('.timebar'),p=$('mapPanel');if(on||document.documentElement.classList.contains('alt-wide'))p.append(t);else p.after(t)}
function expandMap(on){const p=$('mapPanel'),b=$('mapFull'),t=on?J('Close expanded map','地図の拡大を閉じる'):J('Expand map','地図を拡大');p.classList.toggle('expanded',on);document.body.classList.toggle('mapopen',on);withTime(on);b.setAttribute('aria-pressed',String(on));b.dataset.tip=t;b.setAttribute('aria-label',t);setTimeout(()=>map.invalidateSize(),50)}
function updateFilters(){const b=$('filtersButton');if(!b)return;const n=['pref','line','type','size','age'].filter(k=>state[k]!==DEFAULTS[k]).length;b.textContent=n?J(`Filters · ${n} set`,`絞り込み · ${n}件`):J('Filters','絞り込み')}

// Shareable state: the address carries station, period, view, filters, sort and comparison (defaults are left out).
let SLUG=[],BY_SLUG={},LINE_SLUG={},SLUG_LINE={};
const VIEW={price:'price',growth:'change',count:'sales'},VIEW_BACK={price:'price',change:'growth',sales:'count'},yearOf=p=>D.periods[p].slice(0,4);
function writeURL(){const q=new URLSearchParams();if(selected!=null)q.set('s',SLUG[selected]);if(state.unit!==(E.unitHome&&HOMES()?'home':'m2'))q.set('unit',state.unit);if(MAG)q.set('mag',+MAG.toPrecision(3));if(state.period!==D.periods.length-1)q.set('p',yearOf(state.period));if(state.metric!=='price')q.set('view',VIEW[state.metric]);if(state.baseline!==DEFAULTS.baseline)q.set('base',yearOf(state.baseline));for(const d of E.dims)if(state[d]!==DEFAULTS[d])q.set(d,state[d]);if(state.pref)q.set('pref',slug(prefName(state.pref)));if(!showText)q.set('text','0');if(state.line)q.set('line',LINE_SLUG[state.line]);if(state.sortKey!==DEFAULTS.sortKey||state.sortDir!==DEFAULTS.sortDir)q.set('sort',`${state.sortKey}-${state.sortDir<0?'desc':'asc'}`);if(compare.length)q.set('cmp',compare.map(i=>SLUG[i]).join(','));const here=new URLSearchParams(location.search),t=here.get('theme');if(t)q.set('theme',t);if(here.get('lang'))q.set('lang',JA?'ja':'en');const s=q.toString(),path=E.cities?MAP_ROOT+(E.city?E.city.key+'/':''):location.pathname;try{history.replaceState(null,'',path+(s?'?'+s:''))}catch(e){}magLinks()}
function readURL(){const q=new URLSearchParams(location.search),per=y=>{const i=D.periods.findIndex(p=>p.startsWith(y));return i<0?null:i};
if((q.get('unit')||(E.unitHome?'home':'m2'))==='home'&&HOMES()&&!isLand()){state.unit='home';usePeriods()}{const m=+q.get('mag');if(m>=1/8&&m<=64)MAG=2**(Math.round(4*Math.log2(m))/4)}{const a=(q.get('at')||'').split(',').map(Number);if(a.length===3&&a.every(isFinite)&&a[2]>=1/8&&a[2]<=64&&map.options.maxBounds.contains([a[0],a[1]]))AT=[L.latLng(a[0],a[1]),Math.max(map.getMinZoom(),Math.min(map.getMaxZoom(),Math.round(4*zOf(a[2]))/4))]}if(q.get('p')&&per(q.get('p'))!=null)state.period=per(q.get('p'));if(q.get('base')&&per(q.get('base'))!=null)state.baseline=per(q.get('base'));if(VIEW_BACK[q.get('view')])state.metric=VIEW_BACK[q.get('view')];
for(const k of E.dims){const raw=q.get(k);if(raw){const v=+raw;if(Number.isInteger(v)&&v>=0&&v<=E.ranges[k])state[k]=v}}if(isLand()){state.size=0;state.age=0}const pf=Object.entries(D.prefectures).find(([,n])=>slug(n)===q.get('pref')),pg=[...new Set(Object.values(D.pref_groups||{})),...(E.outer||[])].find(n=>slug(n)===q.get('pref'));if(pf)state.pref=pf[0];else if(pg)state.pref='g:'+pg;if(SLUG_LINE[q.get('line')])state.line=SLUG_LINE[q.get('line')];if(q.get('text')==='0')showText=false;
const so=/^(name|pref|price|change|sales)-(asc|desc)$/.exec(q.get('sort')||'');if(so){state.sortKey=so[1];state.sortDir=so[2]==='asc'?1:-1}compare=[...new Set((q.get('cmp')||'').split(',').map(k=>BY_SLUG[k]).filter(i=>i!=null))].slice(0,3);return BY_SLUG[q.get('s')]}
function toast(t,long){const el=$('toast');el.textContent=t;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,long?8000:2500)}
// A link to exactly this view: the address with the clear area's centre and the magnification (at=lat,lon,mag), which opens
// the same view once, in place of the city's opening.
async function copyView(){writeURL();const c=viewCentre(),url=location.href+(location.search?'&':'?')+'at='+[c.lat.toFixed(4),c.lng.toFixed(4),+magOf(map.getZoom()).toPrecision(3)].join(',');track('share',{method:'view_link'});
  try{await navigator.clipboard.writeText(url);toast(J('Link to this view copied','この表示へのリンクをコピー済み'))}catch(e){toast(J('Copy this link: ','このリンクをコピー：')+url,true)}}
async function copyLink(){writeURL();track('share',{method:'copy_link'});const url=location.href;try{await navigator.clipboard.writeText(url);toast(J('Link copied','リンクをコピー済み'))}catch(e){toast(J('Copy this link: ','このリンクをコピー：')+url,true)}}

// Presets: one-tap starting views; any later change clears the highlight.
function markPreset(){document.querySelectorAll('#presets button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.preset===activePreset)))}
function changed(){activePreset='';markPreset();writeURL()}
const CONTROLS=['pref','line','type','size','age','baseline'];
function syncControls(){for(const id of CONTROLS)if($(id))$(id).value=state[id];for(const id of ['size','age'])if($(id))$(id).disabled=isLand()||noBands();const hb=document.querySelector('#unit [data-v=home]');if(hb)hb.disabled=isLand();document.querySelectorAll('#unit button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.v===state.unit)));$('period').value=state.period;document.querySelectorAll('#metric button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.v===state.metric)))}
// Leaflet drops a zoom requested while another is animating, so the start-up fits run without animation.
function fitVisible(animate=true){const ss=D.stations.filter(visible);if((state.pref||state.line)&&ss.length)map.fitBounds(L.latLngBounds(ss.map(s=>[s.lat,s.lon])),{...clearPad(30),maxZoom:12,animate});else openCity(E.city||E.cities[0],animate)}
// data.json holds the opening view only: all homes at every size and age together. The size and age bands of all homes
// (cells-0.json) and each other property type (cells-1.json…) load the first time a filter needs them.
let loadedCells={};
// Switching between the two keeps the latest window if it was showing (the UK's per-home timeline is one window longer).
function usePeriods(){const P=state.unit==='home'?D.homes.periods:D.m2_periods,atEnd=state.period===D.periods.length-1,last=P.length-1;if(P===D.periods)return;D.periods=P;if(atEnd||state.period>last)state.period=last;if(state.baseline>last)state.baseline=DEFAULTS.baseline;$('period').max=last;const t=document.querySelector('.ticks span:last-child');if(t)t.textContent=P[last].slice(0,5)+P[last].slice(7);$('baseline').innerHTML='';P.forEach((p,i)=>$('baseline').add(new Option(p,i)));const y=P[last].slice(-4);document.querySelectorAll('.intro p span').forEach(e=>e.textContent=e.textContent.replace(/2006([–〜])20\d\d/,`2006$1${y}`));$('headline').textContent=E.headline()}
// The switch and its Data & method note are added by the script, so a map gains them as soon as its build makes the files.
function unitSwitch(){const f=document.createElement('div');f.className='field';f.innerHTML=`<span class="fieldlabel" id="unitName"><span class="l-en">Prices</span><span class="l-ja">価格の単位</span></span><div class="seg" id="unit" role="group" aria-labelledby="unitName"><button type="button" data-v="m2"><span class="l-en">Per m²</span><span class="l-ja">㎡単価</span></button><button type="button" data-v="home"><span class="l-en">Per home</span><span class="l-ja">1戸あたり</span></button></div>`;$('metric').closest('.field').after(f);
  $('metric').querySelector('[data-v=price]').innerHTML='<span class="l-en">Price</span><span class="l-ja">価格</span>';f.querySelectorAll('button').forEach(b=>b.onclick=()=>setUnit(b.dataset.v));
  const n=document.createElement('section');n.id='homesNote';n.innerHTML=E.homesNote?`<div class="l-en"><h3>Prices per home</h3><p>${E.homesNote.en}</p></div><div class="l-ja"><h3>1戸あたりの価格</h3><p>${E.homesNote.ja}</p></div>`:D.homes.bands?`<div class="l-en"><h3>Prices per home</h3><p>The Per home switch shows the median total price of the homes sold instead of the price per m². It is what buyers pay, but it mixes location with size: stations where small apartments sell look cheaper per home than per m², and those where large houses sell look dearer. It uses the same sales and filters as the price per m²; land is priced per m² only.</p></div><div class="l-ja"><h3>1戸あたりの価格</h3><p>「1戸あたり」に切り替えると、㎡単価の代わりに取引された住宅の総額の中央値を示す。買い手が実際に払う額だが、立地と広さが混ざる。小さな住戸が多く売れる駅は㎡単価で見るより安く、大きな戸建てが多い駅は高く見える。㎡単価と同じ取引と絞り込みを使う。土地は㎡単価のみである。</p></div>`:`<div class="l-en"><h3>Prices per home</h3><p>The Per home switch shows the median total price of the homes sold instead of the price per m². It is what buyers pay, but it mixes location with size: stations where small flats sell look cheaper per home than per m², and those where large houses sell look dearer. It uses every Land Registry standard sale, with or without an energy certificate, so its samples are larger and it runs to ${D.homes.periods[D.homes.periods.length-1]}; the size and era filters do not apply, as floor areas and ages come from the certificates.</p></div><div class="l-ja"><h3>1戸あたりの価格</h3><p>「1戸あたり」に切り替えると、㎡単価の代わりに取引された住宅の総額の中央値を示す。買い手が実際に払う額だが、立地と広さが混ざる。小さなフラットが多く売れる駅は㎡単価で見るより安く、大きな住宅が多い駅は高く見える。エネルギー証明書の有無にかかわらず土地登記所の標準取引をすべて使うため、件数が多く、${D.homes.periods[D.homes.periods.length-1]}年まで示す。床面積と建築年代は証明書から取るので、広さと年代の絞り込みは使えない。</p></div>`;$('analyticsNote').before(n)}
async function setUnit(u){if(u===state.unit||u==='home'&&isLand())return;state.unit=u;if(noBands()){state.size=0;state.age=0}usePeriods();track('change_unit',{unit:u});await ensureCells();syncControls();render();changed()}
async function ensureCells(){if(state.unit==='home'){const f=D.homes.split?state.type:0;if(loadedCells['h'+f])return;const {keys,rows}=await getJSON(`homes-${f}.json`);rows.forEach((c,i)=>{const s=D.stations[i];s.hcells=Object.assign(s.hcells||{},unpackCells(keys,c))});loadedCells['h'+f]=true;return}const f=state.type?state.type:state.size||state.age?0:null;if(f==null||loadedCells[f])return;const {keys,rows}=await getJSON(`cells-${f}.json`);rows.forEach((c,i)=>Object.assign(D.stations[i].cells,unpackCells(keys,c)));loadedCells[f]=true}
// The deploy (scripts/stamp.py) stamps each script and data URL with a hash of that file (?v=<sha8>) and gives each map page a
// table of its own data files' hashes (<script type="application/json" id="files">): a file in the table is fetched with its
// hash and may be kept by the browser; any other is revalidated (cache:'no-cache'), as is every file of a local build, whose
// URLs still carry the literal BUILD. DATA_FORMAT changes whenever the data's shape does.
const VERSION=(document.currentScript&&new URL(document.currentScript.src).searchParams.get('v'))||'',DATA_FORMAT=6;
const FILES=(()=>{try{return JSON.parse(document.getElementById('files').textContent)}catch(e){return {}}})();
// The site root (app.js lives there), for the shared cities.json: the menu and the links between maps.
const SITE_ROOT=document.currentScript?new URL('.',document.currentScript.src):new URL('../',document.baseURI);
const CITIES=()=>window.EkiSearch&&window.EkiSearch.cities?window.EkiSearch.cities():fetch(new URL('cities.json',SITE_ROOT),{cache:'no-cache'}).then(r=>r.json());
// Data files resolve against the page's address as loaded: the address bar later moves to the city's own page (/shutoken/tokyo/),
// which has no data of its own, so a file fetched after that from the map's own address would 404.
const PAGE_BASE=document.baseURI;
async function getJSON(p){const h=FILES[p],r=await fetch(new URL(h?`${p}?v=${h}`:VERSION==='BUILD'?`${p}?v=BUILD`:p,PAGE_BASE),h?{}:{cache:'no-cache'});if(!r.ok)throw Error(J(`Could not load ${p}`,`${p} を読み込めなかった`));return r.json()}
async function applyPreset(k){const [name,set]=E.presets[k];track('select_preset',{preset:name.en});state={...DEFAULTS,unit:state.unit,period:D.periods.length-1,...set};await ensureCells();syncControls();render();fitVisible();activePreset=String(k);markPreset();writeURL()}

function showStation(idx,pan=false,user=false){selected=idx;if(user)track('select_station',{station:label(D.stations[idx])});const s=D.stations[idx],c=cell(s),g=growth(s),base=cell(s,state.baseline),ev=s.events||[];
const mix=state.type||state.size||state.age?null:state.unit==='home'&&!D.homes.split?[1,2,3,4].map(t=>{const c=(s.hcells||{})[`${state.period}-${t}-0-0`];return c==null?0:typeof c==='number'?c:c[0]}):s.mix?s.mix[state.period]:null,mixTotal=mix?mix.reduce((a,b)=>a+b,0):0;
const where=E.ja?(JN()?`${esc(prefLabel(s.pref))} / <span lang="ja">${esc(s.city)}</span>`:`${esc(D.prefectures[s.pref])} / ${esc(s.city_en||s.city)}`):esc(s.city)+(E.outer&&D.pref_groups&&D.pref_groups[s.pref]!==E.outer[0]?', '+esc(D.pref_groups[s.pref]):'');
$('detail').innerHTML=`<p class="eyebrow">${where}</p><h2 class="stationtitle">${both(s)}</h2><div class="linechips">${s.lines.map(l=>{const [ln,op]=lineLabel(l);return `<div${JN()?' lang="ja"':''}>${esc(ln)}${op&&op!==ln?` · ${esc(op)}`:''}</div>`}).join('')}</div>${s.pooled?`<p class="muted">${T(E.pooled)}</p>`:''}${E.noSales&&!s.total?`<p class="muted">${T(E.noSales)}</p>`:''}<p class="eyebrow">${D.periods[state.period]} · ${T(OBS())}</p><div class="bigprice">${money(c[1])}${PH()?'':'<small> / m²</small>'}</div><p class="pricecaption">${c[1]==null?(MED()?J('No suburb within 1.2 km has a median with these filters.','この条件では1.2 km以内に中央値のある郊外がない。'):J('Fewer than 5 observations with these filters.','この条件では取引が5件未満である。')):thin(c)?J(`Indicative: only ${c[0]} sales with these filters, too few for a range.`,`参考値：この条件の取引は${c[0]}件のみで、範囲を示すには少なすぎる。`):c[2]==null?T(E.noRange||{en:'The source publishes medians only, so there is no range.',ja:'出典は中央値だけを公表しており、範囲はない。'}):J(`Middle 50%: ${E.cur}${fmt(c[2])}–${fmt(c[3])}${UE()}`,`中央50%：${MAN()?`${man(c[2])}〜${man(c[3])}`:`${E.cur}${fmt(c[2])}〜${fmt(c[3])}${UJ()}`}`)}</p><div class="growth"><strong class="${g==null?'':g>=0?'up':'down'}">${pct(g)}</strong> ${J(`vs ${D.periods[state.baseline]} <small>(${fmt(base[0])} baseline ${MED()?'medians':'sales'})</small>`,`（${D.periods[state.baseline]}比） <small>基準期間の${MED()?'中央値':'取引'}${fmt(base[0])}件</small>`)}</div><div class="statgrid"><div><span>${MED()?J('Suburb medians','郊外の中央値'):J('Transactions','取引件数')}</span><strong>${fmt(c[0])}</strong></div>${noArea()?'':`<div><span>${isLand()?J('Median plot area','土地面積の中央値'):J('Median floor area','床面積の中央値')}</span><strong>${fmt(c[4])} m²</strong></div>`}<div><span>${T(E.stats[0][0])}</span><strong>${c[5]==null?'—':E.stats[0][1](c[5])}</strong></div><div><span>${T(E.stats[1][0])}</span><strong>${c[6]==null?'—':E.stats[1][1](c[6])}</strong></div></div>${mixTotal?`<p class="mix">${T(E.mixLabels).map((t,k)=>`${t} ${Math.round(100*mix[k]/mixTotal)}%`).join(' · ')}</p>`:''}<div class="chartbar"><b>${J('Price history','価格の推移')} · ${T(HX('chartUnit'))}</b><div class="tools" id="stationTools"></div></div><div id="stationChart">${tableView.station?chartTable(stationRows(idx)):drawChart([idx],ev)}</div>${eventsKey(ev)}<p class="muted">${T(E.note)}</p><button class="comparebutton" id="addCompare">${compare.includes(idx)?J('Added to comparison','比較に追加済み'):compare.length>=3?J('Comparison full (3 stations)','比較は3駅まで'):J('Add to comparison','比較に追加')}</button>`;
const flip=()=>{tableView.station=!tableView.station;showStation(idx)};
panelTools($('stationTools'),{button:{icon:'table',label:viewLabel(tableView.station),pressed:tableView.station,onClick:flip},menu:[{label:viewLabel(tableView.station),onClick:flip},{label:J('Download CSV','CSVをダウンロード'),onClick:()=>downloadCsv(`ekinomics-${SLUG[idx]}.csv`,stationRows(idx))},{label:J('Download PNG','PNGをダウンロード'),hide:tableView.station,onClick:()=>svgPng($('stationChart').querySelector('svg'),`ekinomics-${SLUG[idx]}`)},{label:J('Full screen','全画面'),hide:!canFull,onClick:()=>toggleFull($('detail'))}]});
$('addCompare').onclick=()=>{if(compare.includes(idx)||compare.length>=3)return;track('add_comparison',{station:label(s)});compare.push(idx);renderCompare();showStation(idx);changed()};
markers.forEach((m,i)=>m.setStyle(markerStyle(i)));compare.forEach(i=>map.hasLayer(markers[i])&&markers[i].bringToFront());markers[idx].bringToFront();if(pan)centre([s.lat,s.lon],Math.max(map.getZoom(),12));drawLabels();if(user)changed()}
function renderCompare(){$('compareChips').innerHTML=compare.map((i,j)=>`<button data-remove="${i}" style="border-left-color:${colours[j]}">${both(D.stations[i])} ×</button>`).join('');$('compareChart').innerHTML=compare.length?(tableView.compare?chartTable(compareRows()):`<div class="chartbar"><b>${T(HX('chartUnit'))}</b></div>${drawChart(compare)}`):'';
document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{compare=compare.filter(i=>i!==+b.dataset.remove);renderCompare();if(selected!=null)showStation(selected);else{markers.forEach((m,i)=>m.setStyle(markerStyle(i)));drawLabels()}changed()});
const flip=()=>{tableView.compare=!tableView.compare;renderCompare()};
panelTools($('compareTools'),compare.length?{button:{icon:'table',label:viewLabel(tableView.compare),pressed:tableView.compare,onClick:flip},menu:[{label:viewLabel(tableView.compare),onClick:flip},{label:J('Download CSV','CSVをダウンロード'),onClick:()=>downloadCsv('ekinomics-comparison.csv',compareRows())},{label:J('Download PNG','PNGをダウンロード'),hide:tableView.compare,onClick:()=>svgPng($('compareChart').querySelector('svg'),'ekinomics-comparison')},{label:J('Full screen','全画面'),hide:!canFull,onClick:()=>toggleFull($('comparePanel'))}]}:{})}
// Rankings sort by any column; price rankings need 30 sales, change needs 20 in both windows.
function rankingRows(){const key=state.sortKey,dir=state.sortDir;let ss=D.stations.map((s,i)=>({s,i,c:cell(s),g:growth(s)})).filter(x=>visible(x.s));
ss=ss.filter({price:x=>x.c[0]>=(MED()?1:RANK_MIN),change:x=>x.g!=null,sales:x=>x.c[0]>0}[key]||(x=>x.c[1]!=null));
const val={name:x=>nm(x.s).toLowerCase(),pref:x=>prefLabel(x.s.pref)+' '+nm(x.s).toLowerCase(),price:x=>x.c[1],change:x=>x.g,sales:x=>x.c[0]}[key];return ss.sort((a,b)=>{const A=val(a),B=val(b);return (A>B?1:A<B?-1:0)*dir})}
