const table=`<div class="tablewrap"><table>${heads(JA?['年','再販','対象','使用']:['Year','Resales','Eligible','Used'])}<tbody>${years.map(([y,v])=>`<tr><td>${y}</td><td>${fmt(v.raw)}</td><td>${fmt(v.eligible)}</td><td>${fmt(v.used||0)}</td></tr>`).join('')}</tbody></table></div>`;
