function zoneCoverage(){const c=D.coverage,k=c.counts,z=E.zone||{min:5,since:2004,unit:'zone',en:'zones',ja:'ゾーン',enLong:'data zones',jaLong:'データゾーン',saleEn:'residential sales at market value',saleJa:'市場価格での住宅取引'},s=`price suppressed at source (under ${z.min} sales in a ${z.unit} and year)`,years=Object.entries(c.by_year).filter(([y])=>+y>=2006),[by,bm,bd]=D.built.split('-').map(Number);
const table=`<div class="tablewrap"><table>${heads(JA?['年',`対象地域の${z.ja}の取引`,'価格あり・駅に計上',`価格非公表（${z.ja}${z.min}件未満）`]:['Year',`Sales in the area's ${z.en}`,'With a price, at a station',`Price suppressed (${z.unit} under ${z.min})`])}<tbody>${years.map(([y,v])=>`<tr><td>${y}</td><td>${fmt(v.sales)}</td><td>${fmt(v.used||0)}</td><td>${fmt(v.suppressed||0)}</td></tr>`).join('')}</tbody></table></div>`;
return JA?`<p>${by}年${bm}月${bd}日作成、2023年までの取引による。対象地域の${fmt(c.districts)}自治体にある${fmt(c.zones)}の${z.jaLong}で、${z.since}年以降の${z.saleJa}は${fmt(k.raw)}件である。そのうち価格が公表され、2006年以降の期間にあり、${fmt(c.sites_shown)}駅のいずれかから${c.radius_km} km以内の${z.ja}の取引${fmt(k.priced)}件を使う。</p>${table}<p>使っていないもの：中心が駅から${c.radius_km} kmより遠い${z.ja}の取引${fmt(k['more than 1.2 km from a station'])}件、2006年より前${D.source_period.endsWith('2024')?'と2024年':''}の取引${fmt(k['outside windows'])}件、その年の取引が${z.min}件未満で価格が公表されていない${z.ja}の取引${fmt(k[s]||0)}件${k['nearest station outside the atlas area']?`、対象地域外の駅が最寄りの${z.ja}の取引${fmt(k['nearest station outside the atlas area'])}件`:''}。</p>`
:`<p>Built ${bd} ${['January','February','March','April','May','June','July','August','September','October','November','December'][bm-1]} ${by} from sales up to 2023. The atlas area's ${fmt(c.districts)} councils hold ${fmt(c.zones)} ${z.enLong} with ${fmt(k.raw)} ${z.saleEn} since ${z.since}. ${fmt(k.priced)} of them, in ${z.en} with a published price, fall in the windows from 2006 and in ${z.en} within ${c.radius_km} km of one of ${fmt(c.sites_shown)} stations.</p>${table}<p>Left out: ${fmt(k['more than 1.2 km from a station'])} sales in ${z.en} whose centre is more than ${c.radius_km} km from a station, ${fmt(k['outside windows'])} ${D.source_period.endsWith('2024')?'before 2006 or in 2024':'before 2006'}, and ${fmt(k[s]||0)} in ${z.en} with under ${z.min} sales that year, whose prices are not published${k['nearest station outside the atlas area']?`, plus ${fmt(k['nearest station outside the atlas area'])} in ${z.en} nearest a station outside the atlas area`:''}.</p>`}
function japanCoverage(){const hid=c=>!D.prefectures[c],pn=c=>D.prefectures[c]?prefLabel(c):D.coverage[c].name,ns=J(' <small>(not shown)</small>',' <small>（非表示）</small>');
return `<p>${J('Downloaded 24 October 2026. ','2026年10月24日にダウンロード。')}${T(E.scope)}${J(' Station matching and eligibility losses are shown below.','駅の照合と対象外となった件数は以下のとおりである。')}</p><div class="tablewrap"><table>${heads(JA?['都道府県','元データ','対象','照合済み','2006〜25年']:['Prefecture','Source','Eligible','Matched','2006–25'])}<tbody>`+Object.entries(D.coverage).sort(([a,x],[b,y])=>hid(a)-hid(b)||y.raw-x.raw).map(([code,c])=>`<tr><td>${esc(pn(code))}${hid(code)?ns:''}</td><td>${fmt(c.raw)}</td><td>${fmt(c.eligible)}</td><td>${fmt(c.matched)}</td><td>${fmt(c.in_windows)}</td></tr>`).join('')+`</tbody></table></div><p>${J('Eligible records exclude ','対象件数からは次を除いている：')}${JA?reasons(D.exclusions):Object.entries(D.exclusions).map(([r,v])=>`${fmt(v)} ${esc(r)}`).join('; ')}${J('.','。')}</p>`+(D.type_coverage?`<p>${J('Houses and land: sales in the 2006–25 windows, after the same exclusions.','戸建てと土地：2006〜25年の期間の取引（同じ除外の後）。')}</p><div class="tablewrap"><table>${heads(JA?['都道府県','戸建て','土地']:['Prefecture','Houses','Land'])}<tbody>`+Object.entries(D.type_coverage).map(([c,v])=>`<tr><td>${D.prefectures[c]?esc(pn(c)):esc(D.hidden_prefectures[c])+ns}</td><td>${fmt((v.houses||{}).in_windows)}</td><td>${fmt((v.land||{}).in_windows)}</td></tr>`).join('')+'</tbody></table></div>':'')}
// Language switch. Static text swaps by CSS (span pairs); options and attributes swap from data-ja*; drawn text re-renders.
const SWAP=[['ja',null],['jaLabel','aria-label'],['jaTip','data-tip'],['jaPlaceholder','placeholder']];
function applyStatic(){for(const [k,attr] of SWAP)document.querySelectorAll(`[data-${k.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())}]`).forEach(el=>{const store='en'+k.slice(2);if(el.dataset[store]==null)el.dataset[store]=attr?el.getAttribute(attr)||'':el.textContent;const v=JA?el.dataset[k]:el.dataset[store];if(attr)el.setAttribute(attr,v);else el.textContent=v})}
function markLang(){document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.lang==='ja')===JA)))}
function controlLabels(){document.querySelectorAll('#presets button[data-preset]').forEach(b=>b.textContent=T(E.presets[+b.dataset.preset][0]));
document.querySelectorAll('#goto button[data-city]').forEach(b=>b.textContent=cityLabel(E.cities.find(c=>c.key===b.dataset.city)));
const g=$('gotoMenu');if(g){g.setAttribute('aria-label',J('Go to','移動'));g.options[0].text=J('Go to…','移動…');[...g.options].slice(1).forEach(o=>o.text=cityLabel(E.cities.find(c=>c.key===o.value)))}
tip($('resetMap'),J('Reset view','表示をリセット'));textButton();if(!canFull)expandMap($('mapPanel').classList.contains('expanded'));updateFilters();NEAR.forEach(({f,m})=>m.setIcon(nearIcon(f)));
const sh=$('sheet');if(sh){sh.querySelector('.sheetclose').setAttribute('aria-label',J('Close details','詳細を閉じる'));sh.querySelector('.grab').setAttribute('aria-label',sh.classList.contains('expanded')?J('Collapse details','詳細を縮める'):J('Expand details','詳細を広げる'))}
if($('legend').getAttribute('role'))$('legend').setAttribute('aria-label',J('Legend','凡例'))}
function applyLang(){document.documentElement.lang=JA?'ja':'en';markLang();applyStatic();const eb=document.querySelector(`.brand .eyebrow .l-${JA?'ja':'en'}`);if(eb)document.title='Ekinomics · '+eb.textContent;
if(!D||!map)return;buildSelects();syncControls();controlLabels();$('headline').textContent=E.headline();$('coverage').innerHTML=(E.coverage||(E.ja?japanCoverage:londonCoverage))();render()}
// The Japanese font's stylesheet (90 KB, mostly Plex Sans JP's pieces) loads only for the Japanese interface: each page's head
// script adds it for a Japanese first view, and switching to Japanese adds it here.
function jaFont(){if(!document.querySelector('link[data-ja-font]'))document.head.insertAdjacentHTML('beforeend','<link rel="stylesheet" data-ja-font href="https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+JP:wght@400;500;600&display=swap">')}
function setLang(l){JA=l==='ja';if(JA)jaFont();try{localStorage.setItem(LANG_KEY,l)}catch(e){}track('change_language',{language:l});applyLang();if(D)writeURL()}
// Analytics: Google Analytics 4 as on 3rdcultures.com, loaded only on the live domain (not staging or local copies).
// The address changes on every interaction to keep links shareable, so the GA stream's "page changes based on browser
// history events" setting must stay off; interactions are counted as the few named events below instead.
const GA_ID='G-QD6CPSEF5M';
function startAnalytics(){if(!GA_ID)return;$('analyticsNote').hidden=false;if(location.hostname!=='ekinomics.com')return;const s=document.createElement('script');s.async=true;s.src='https://www.googletagmanager.com/gtag/js?id='+GA_ID;document.head.appendChild(s);window.dataLayer=window.dataLayer||[];window.gtag=function(){dataLayer.push(arguments)};gtag('js',new Date());gtag('config',GA_ID)}
function track(name,params={}){if(window.gtag)gtag('event',name,{edition:D?D.edition||'tokyo':'',...params})}
// The place menu is a disclosure: the button shows and hides the region links; Escape or a click elsewhere closes it.
(()=>{const b=$('placeButton'),m=$('placeMenu');if(!b)return;const set=open=>{m.hidden=!open;b.setAttribute('aria-expanded',String(open))};b.onclick=e=>{e.stopPropagation();set(m.hidden)};document.addEventListener('click',e=>{if(!m.hidden&&!m.contains(e.target))set(false)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!m.hidden){set(false);b.focus()}})})();
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));applyLang();
startAnalytics();
start().catch(e=>{console.error(e);$('headline').textContent=J('The atlas could not load.','アトラスを読み込めなかった。');$('error').hidden=false;$('error').textContent=e.message+J(' — reload to try again.','。再読み込みが必要。');console.error(e)});
